import subprocess,os,json,hashlib,time
from pathlib import Path
root=Path('/dataset/shaoshitong/search-r1-rl/cosearch/author-native')
assert not subprocess.check_output(['squeue','-h','--name=cosearch-author-five','-o','%i'],text=True).strip()
raw=subprocess.check_output(['nvidia-smi','--query-gpu=index,uuid','--format=csv,noheader'],text=True)
mapping={x.split(',')[1].strip():int(x.split(',')[0].strip()) for x in raw.splitlines()}
assert len(mapping)==8
code="""import os,sys,json
assert 'sitecustomize' in sys.modules
assert 'torch' not in sys.modules and 'vllm' not in sys.modules
before=os.environ['CUDA_VISIBLE_DEVICES']
from vllm.platforms import current_platform
from vllm.model_executor.models.registry import _run_in_subprocess,_ModelInfo,ModelRegistry
info=_run_in_subprocess(lambda: _ModelInfo.from_model_cls(ModelRegistry.models['Qwen2ForCausalLM'].load_model_cls()))
assert info is not None
import torch
assert not torch.cuda.is_initialized() and os.environ['CUDA_VISIBLE_DEVICES']==before
actual=[current_platform.device_id_to_physical_device_id(i) for i in range(8)]
values=before.split(',')
assert actual==[json.loads(os.environ['COSEARCH_LEASED_UUID_TO_INDEX'])[u] for u in values] if values[0].startswith('GPU-') else actual==list(range(8))
print(json.dumps(dict(mask_kind='uuid' if values[0].startswith('GPU-') else 'numeric',startup_no_torch=True,qwen_actual_uncached_registry_subprocess_passed=True,physical_indices=actual,cuda_initialized=False,real_rl_updates=0)))
"""
results=[]
for mask in [','.join(mapping),','.join(str(i) for i in range(8))]:
 env=dict(os.environ,CUDA_VISIBLE_DEVICES=mask,COSEARCH_LEASED_UUIDS=','.join(mapping),COSEARCH_LEASED_UUID_TO_INDEX=json.dumps(mapping),PYTHONPATH=str(root/'tools'),HF_HUB_OFFLINE='1')
 for k in ['ROCR_VISIBLE_DEVICES','HIP_VISIBLE_DEVICES','GPU_DEVICE_ORDINAL']:env.pop(k,None)
 r=subprocess.run([str(root/'env/bin/python'),'-c',code],env=env,text=True,capture_output=True,timeout=60)
 print(r.stdout);print(r.stderr[-3000:]);assert r.returncode==0
 results.append(r.stdout)
value=dict(passed=True,results=results,real_rl_updates=0,checked_at=time.time(),tools_sha256={n:hashlib.sha256((root/'tools'/n).read_bytes()).hexdigest() for n in ['observe_worker.py','sitecustomize.py']})
(root/'tools/vllm-registry-subprocess-cpu-gate.json').write_text(json.dumps(value,indent=2))
print(json.dumps(value))
GATE
